/**
 * URL validation shared by the admin API handlers.
 * No imports on purpose: this file is unit-testable without the AWS SDK.
 */

/**
 * Require every listed field that is present and non-empty to be an https: URL.
 * Stored URL fields are rendered as <a href> in the Admin Portal, so a
 * javascript:/data:/http: value must never reach the store (amfa-442 #9).
 *
 * @param {Object} data - request body object
 * @param {string[]} fields - field names to check
 * @throws {Error} statusCode 400, expose true, type 'validation_error', field
 */
export function assertHttpsUrls(data, fields) {
    for (const field of fields) {
        const value = data?.[field];
        if (value === undefined || value === null || value === '') continue;
        let protocol;
        try { protocol = new URL(value).protocol; } catch { /* not an absolute URL */ }
        if (protocol !== 'https:') {
            const error = new Error(`${field}: must be an https:// URL`);
            error.statusCode = 400;
            error.expose = true;
            error.type = 'validation_error';
            error.field = field;
            throw error;
        }
    }
}
